import prisma from '../lib/prisma.js'
import asyncHandler from '../middleware/asyncHandler.js'

// GET /analytics/overview (STAFF, LEADERSHIP only)
export const getOverview = asyncHandler(async (req, res) => {
  const [
    totalUsers,
    totalApplications,
    pendingApplications,
    acceptedApplications,
    activeStudents,
    upcomingEvents,
    activeMous
  ] = await Promise.all([
    prisma.users.count(),
    prisma.applications.count(),
    prisma.applications.count({ where: { current_stage: 'Submitted' } }),
    prisma.applications.count({ where: { current_stage: 'Enrolled' } }),
    prisma.students.count(),
    prisma.events.count({ where: { date: { gte: new Date() }, status: 'published', is_archived: false } }),
    prisma.mous.count({ where: { status: 'Active', is_archived: false } })
  ])

  res.json({
    totalUsers,
    totalApplications,
    pendingApplications,
    acceptedApplications,
    activeStudents,
    upcomingEvents,
    activeMous
  })
})

// GET /analytics/applications (STAFF, LEADERSHIP only)
export const getApplicationsAnalytics = asyncHandler(async (req, res) => {
  // Get count by stage
  const stageGrouping = await prisma.applications.groupBy({
    by: ['current_stage'],  // DB-02 FIX: was 'stage'
    _count: {
      id: true
    }
  })

  // Format stage breakdown
  const stageBreakdown = {}
  stageGrouping.forEach(group => {
    stageBreakdown[group.current_stage] = group._count.id  // DB-02 FIX: was group.stage
  })

  // Get count by program
  const programGrouping = await prisma.applications.groupBy({
    by: ['program_id'],
    _count: {
      id: true
    }
  })

  // Fetch program titles to map IDs to names
  const programIds = programGrouping.map(g => g.program_id)
  const programs = await prisma.programs.findMany({
    where: { id: { in: programIds } },
    select: { id: true, name: true }  // DB-02 FIX: was 'title' (field doesn't exist in schema)
  })

  const programMap = {}
  programs.forEach(p => {
    programMap[p.id] = p.name  // DB-02 FIX: was p.title
  })

  const programBreakdown = programGrouping.map(group => ({
    programId: group.program_id,
    programName: programMap[group.program_id] || 'Unknown Program',
    count: group._count.id
  }))

  res.json({
    stageBreakdown,
    programBreakdown
  })
})

// GET /analytics/events (STAFF, LEADERSHIP only)
export const getEventsAnalytics = asyncHandler(async (req, res) => {
  const [totalEvents, typeGrouping, statusGrouping] = await Promise.all([
    prisma.events.count(),
    prisma.events.groupBy({
      by: ['event_type'],  // DB-02 FIX: was 'type'
      _count: { id: true }
    }),
    prisma.events.groupBy({
      by: ['status'],  // DB-02 FIX: was 'visibility'
      _count: { id: true }
    })
  ])

  res.json({
    totalEvents,
    byType:   typeGrouping.map(g   => ({ type:   g.event_type, count: g._count.id })),
    byStatus: statusGrouping.map(g => ({ status: g.status,     count: g._count.id }))
  })
  })
})

import { z } from 'zod'
import prisma from '../lib/prisma.js'
import asyncHandler from '../middleware/asyncHandler.js'
import { paginate } from '../utils/paginate.js'

const createSchema = z.object({
  targetTable: z.enum(['mous', 'programs', 'events', 'universities', 'users', 'student_records', 'applications', 'documents', 'calendar_events']), // Tables that ADMIN/EDITOR can submit changes for
  targetId: z.string().uuid().nullable().optional(),
  actionType: z.enum(['CREATE', 'UPDATE', 'DELETE']),
  payload: z.record(z.any())
})

// GET /change-requests (SUPER_ADMIN, ADMIN, EDITOR)
export const getChangeRequests = asyncHandler(async (req, res) => {
  const { status, targetTable } = req.query
  const where = {}

  if (status) where.status = status.toUpperCase()
  if (targetTable) where.target_table = targetTable

  // ADMINs and EDITORs can only see their own requests
  if (['EDITOR', 'ADMIN'].includes(req.user.role)) {
    where.requested_by = req.user.id
  }

  const paginatedResult = await paginate(prisma.change_requests, req.query, {
    where,
    include: {
      users_change_requests_requested_byTousers: { select: { id: true, name: true, email: true } },
      users_change_requests_reviewed_byTousers: { select: { id: true, name: true, email: true } }
    },
    orderBy: { created_at: 'desc' }
  })

  res.json({
    data: paginatedResult.data,
    page: paginatedResult.page,
    limit: paginatedResult.limit,
    total: paginatedResult.total
  })
})

// POST /change-requests (ADMIN, EDITOR)
export const createChangeRequest = asyncHandler(async (req, res) => {
  const parsed = createSchema.parse(req.body)

  if (parsed.actionType !== 'CREATE' && !parsed.targetId) {
    return res.status(400).json({ error: { code: 'VALIDATION_ERROR', message: 'targetId is required for UPDATE or DELETE' } })
  }

  const request = await prisma.change_requests.create({
    data: {
      target_table: parsed.targetTable,
      target_id: parsed.targetId || null,
      action_type: parsed.actionType,
      payload: parsed.payload,
      requested_by: req.user.id,
      status: 'PENDING'
    }
  })

  res.status(201).json(request)
})

// PATCH /change-requests/:id/approve (SUPER_ADMIN)
export const approveChangeRequest = asyncHandler(async (req, res) => {
  const { id } = req.params
  const request = await prisma.change_requests.findUnique({ where: { id } })

  if (!request) return res.status(404).json({ error: { code: 'NOT_FOUND', message: 'Request not found' } })
  if (request.status !== 'PENDING') return res.status(400).json({ error: { code: 'BAD_REQUEST', message: 'Request is already processed' } })

  const { target_table, target_id, action_type, payload } = request

  await prisma.$transaction(async (tx) => {
    // Dynamically apply changes based on action type
    if (action_type === 'CREATE') {
      await tx[target_table].create({ data: payload })
    } else if (action_type === 'UPDATE') {
      await tx[target_table].update({ where: { id: target_id }, data: payload })
    } else if (action_type === 'DELETE') {
      await tx[target_table].delete({ where: { id: target_id } })
    }

    await tx.change_requests.update({
      where: { id },
      data: {
        status: 'APPROVED',
        reviewed_by: req.user.id,
        reviewed_at: new Date()
      }
    })
  })

  const updatedRequest = await prisma.change_requests.findUnique({ where: { id } })
  res.json(updatedRequest)
})

// PATCH /change-requests/:id/reject (SUPER_ADMIN)
export const rejectChangeRequest = asyncHandler(async (req, res) => {
  const { id } = req.params
  const request = await prisma.change_requests.findUnique({ where: { id } })

  if (!request) return res.status(404).json({ error: { code: 'NOT_FOUND', message: 'Request not found' } })
  if (request.status !== 'PENDING') return res.status(400).json({ error: { code: 'BAD_REQUEST', message: 'Request is already processed' } })

  const updatedRequest = await prisma.change_requests.update({
    where: { id },
    data: {
      status: 'REJECTED',
      reviewed_by: req.user.id,
      reviewed_at: new Date()
    }
  })

  res.json(updatedRequest)
})

import { DeleteObjectCommand, PutObjectCommand } from '@aws-sdk/client-s3'
import fs from 'fs/promises'
import prisma from '../lib/prisma.js'
import { r2 } from '../lib/r2.js'
import asyncHandler from '../middleware/asyncHandler.js'
import { getSignedR2Url } from '../utils/r2Sign.js'
import { paginate } from '../utils/paginate.js'
import logger from '../lib/logger.js'
import { fileQueue } from '../lib/queues.js'
import { validateFileSignature } from '../services/fileValidationService.js'
import { writeAudit } from '../services/auditService.js'

// Format helper
async function formatDocument(doc, includeUrl = false) {
  if (!doc) return null
  const formatted = {
    id: doc.id,
    userId: doc.user_id,
    applicationId: doc.application_id,
    category: doc.type, // Map DB type to category
    fileName: doc.r2_key.split('/').pop().replace(/^\d+-/, ''), // Extract original filename from key
    status: doc.status,
    verifiedById: doc.verified_by_id,
    verifiedAt: doc.verified_at,
    createdAt: doc.created_at,
    updatedAt: doc.updated_at
  }

  if (includeUrl) {
    formatted.url = await getSignedR2Url(doc.r2_key)
    formatted.urlExpiresAt = new Date(Date.now() + 900 * 1000) // 15 minutes
  }

  return formatted
}

// GET /documents (STAFF, LEADERSHIP, or Owner)
export const getDocuments = asyncHandler(async (req, res) => {
  const { userId, applicationId } = req.query

  const where = {}

  // Enforce access control:
  // - Students and Editors can only view their own documents
  // - SUPER_ADMIN/ADMIN can view all documents
  if (req.user.role === 'student' || req.user.role === 'editor') {
    where.user_id = req.user.id
  } else {
    if (userId) {
      where.user_id = userId
    }
  }

  if (applicationId) {
    where.application_id = applicationId
  }

  const paginatedResult = await paginate(prisma.documents, req.query, {
    where,
    orderBy: { created_at: 'desc' }
  })

  const formattedData = await Promise.all(
    paginatedResult.data.map(doc => formatDocument(doc, false))
  )

  res.json({
    data: formattedData,
    page: paginatedResult.page,
    limit: paginatedResult.limit,
    total: paginatedResult.total
  })
})

// GET /documents/:id (STAFF, LEADERSHIP, or Owner)
export const getDocumentById = asyncHandler(async (req, res) => {
  const { id } = req.params

  const doc = await prisma.documents.findUnique({
    where: { id }
  })

  if (!doc) {
    return res.status(404).json({
      error: { code: 'NOT_FOUND', message: 'Document not found' }
    })
  }

  // SEC-01 FIX: role comparisons use lowercase (matches authenticate.js storage)
  if ((req.user.role === 'student' || req.user.role === 'editor') && doc.user_id !== req.user.id) {
    return res.status(403).json({
      error: { code: 'FORBIDDEN', message: 'Access denied' }
    })
  }

  // AUDIT-01: log document view when a signed URL is generated
  await writeAudit({
    itemId:      doc.id,
    action:      'Updated', // closest AuditAction ΓÇö 'Viewed' not in enum; extend enum if needed
    itemTitle:   doc.r2_key.split('/').pop(),
    itemType:    'Program', // placeholder ΓÇö extend AuditItemType enum to include 'Document'
    performedBy: req.user,
    details:     `Document viewed by ${req.user.email}`
  })

  res.json(await formatDocument(doc, true))
})

// POST /documents (Authenticated - Upload a document)
export const uploadDocument = asyncHandler(async (req, res) => {
  if (!req.file) {
    return res.status(400).json({
      error: { code: 'BAD_REQUEST', message: 'No file uploaded' }
    })
  }

  const { category, applicationId } = req.body

  // Validate category matching the DB doc_type enum
  const docTypes = ['PASSPORT', 'TRANSCRIPT', 'SOP', 'BANK_STATEMENT', 'PHOTO', 'VACCINATION']
  const upperCategory = (category || '').toUpperCase()
  if (!docTypes.includes(upperCategory)) {
    return res.status(400).json({
      error: { code: 'VALIDATION_ERROR', message: 'Invalid category', fields: { category: `Must be one of: ${docTypes.join(', ')}` } }
    })
  }

  // SEC-01 FIX: lowercase role comparison
  if (applicationId) {
    const app = await prisma.applications.findUnique({ where: { id: applicationId } })
    if (!app) {
      return res.status(400).json({
        error: { code: 'VALIDATION_ERROR', message: 'Application not found', fields: { applicationId: 'Application does not exist' } }
      })
    }
    if ((req.user.role === 'student' || req.user.role === 'editor') && app.student?.user_id !== req.user.id) {
      return res.status(403).json({
        error: { code: 'FORBIDDEN', message: 'Access denied' }
      })
    }
  }

  // SEC-02 FIX: server-side file signature validation before anything else
  const validation = await validateFileSignature(
    req.file.path,
    req.file.mimetype,
    req.file.originalname
  )
  if (!validation.valid) {
    // Clean up the rejected temp file immediately
    await fs.unlink(req.file.path).catch(() => {})
    return res.status(400).json({
      error: { code: 'INVALID_FILE', message: 'File failed security validation', details: validation.errors }
    })
  }

  const sanitizedFilename = req.file.originalname.replace(/[^a-zA-Z0-9.-]/g, '_')
  const r2Key = `documents/${req.user.id}/${Date.now()}-${sanitizedFilename}`

  // SEC-06 FIX: upload directly to R2 in the API handler (not in the worker)
  // This makes the flow multi-server safe ΓÇö workers never touch local disk paths.
  let fileBuffer
  try {
    fileBuffer = await fs.readFile(req.file.path)
    await r2.send(new PutObjectCommand({
      Bucket: process.env.R2_BUCKET_NAME || 'documents',
      Key: r2Key,
      Body: fileBuffer,
      ContentType: req.file.mimetype
    }))
  } finally {
    // Always clean up temp file regardless of outcome
    await fs.unlink(req.file.path).catch(() => {})
  }

  // Persist to DB ΓÇö file is now safely in R2
  const doc = await prisma.documents.create({
    data: {
      user_id:        req.user.id,
      application_id: applicationId || null,
      type:           upperCategory,
      r2_key:         r2Key,
      status:         'PENDING'
    }
  })

  // Enqueue post-processing job with R2 key (not local path)
  await fileQueue.add('scanDocument', {
    documentId: doc.id,
    r2Key:      r2Key,
    userId:     req.user.id
  })

  res.status(201).json(await formatDocument(doc, false))
})

// PATCH /documents/:id/verify (STAFF, LEADERSHIP only)
export const verifyDocument = asyncHandler(async (req, res) => {
  const { id } = req.params
  const { verificationStatus } = req.body

  if (verificationStatus !== 'verified' && verificationStatus !== 'rejected') {
    return res.status(400).json({
      error: { code: 'VALIDATION_ERROR', message: 'Invalid verificationStatus', fields: { verificationStatus: 'Must be verified or rejected' } }
    })
  }

  const doc = await prisma.documents.findUnique({ where: { id } })
  if (!doc) {
    return res.status(404).json({
      error: { code: 'NOT_FOUND', message: 'Document not found' }
    })
  }

  // Map "verified" -> VERIFIED. If "rejected", we revert/keep status as PENDING since DB has no REJECTED value.
  const dbStatus = verificationStatus === 'verified' ? 'VERIFIED' : 'PENDING'

  const updated = await prisma.documents.update({
    where: { id },
    data: {
      status:         dbStatus,
      verified_by_id: req.user.id,
      verified_at:    new Date(),
      updated_at:     new Date()
    }
  })

  // AUDIT-01: log verification
  await writeAudit({
    itemId:        doc.id,
    action:        verificationStatus === 'verified' ? 'Approved' : 'Rejected',
    itemTitle:     doc.r2_key.split('/').pop(),
    itemType:      'Program', // placeholder ΓÇö extend AuditItemType to include 'Document'
    performedBy:   req.user,
    previousValue: doc.status,
    newValue:      dbStatus,
    details:       `Document ${verificationStatus} by ${req.user.email}`
  })

  res.json(await formatDocument(updated, false))
})

// DELETE /documents/:id (Owner before verification, or LEADERSHIP)
export const deleteDocument = asyncHandler(async (req, res) => {
  const { id } = req.params

  const doc = await prisma.documents.findUnique({ where: { id } })
  if (!doc) {
    return res.status(404).json({
      error: { code: 'NOT_FOUND', message: 'Document not found' }
    })
  }

  // Delete permissions:
  // - Students/Editors can only delete their OWN document if it is still PENDING
  // - SUPER_ADMIN and ADMIN can delete any document
  // SEC-01 FIX: use lowercase role names
  if (req.user.role !== 'super_admin' && req.user.role !== 'admin') {
    if (doc.user_id !== req.user.id) {
      return res.status(403).json({
        error: { code: 'FORBIDDEN', message: 'Access denied' }
      })
    }
    if (doc.status === 'VERIFIED') {
      return res.status(400).json({
        error: { code: 'BAD_REQUEST', message: 'Verified documents cannot be deleted' }
      })
    }
  }

  // Delete from Cloudflare R2
  try {
    await r2.send(new DeleteObjectCommand({
      Bucket: process.env.R2_BUCKET_NAME || 'documents',
      Key: doc.r2_key
    }))
  } catch (err) {
    logger.error('Failed to delete object from R2:', doc.r2_key, err)
  }

  // DATA-02 FIX: soft delete ΓÇö set deleted_at instead of hard deleting
  await prisma.documents.update({
    where: { id },
    data: { deleted_at: new Date(), updated_at: new Date() }
  })

  // AUDIT-01: log deletion
  await writeAudit({
    itemId:      doc.id,
    action:      'Deleted',
    itemTitle:   doc.r2_key.split('/').pop(),
    itemType:    'Program', // placeholder ΓÇö extend AuditItemType to include 'Document'
    performedBy: req.user,
    details:     `Document deleted by ${req.user.email}`
  })

  res.json({ message: 'Document deleted successfully' })
})

import Redis from 'ioredis'
import logger from './logger.js'

// Connect using REDIS_URL if provided (common in PaaS like Coolify, Render, Heroku)
// Otherwise fallback to individual host/port/password variables
const redisConfig = process.env.REDIS_URL 
  ? process.env.REDIS_URL 
  : {
      host: process.env.REDIS_HOST || '127.0.0.1',
      port: process.env.REDIS_PORT || 6379,
      password: process.env.REDIS_PASSWORD || undefined,
    }

export const redis = new Redis(redisConfig, {
  maxRetriesPerRequest: null, // Required by BullMQ
  retryStrategy(times) {
    return Math.min(times * 100, 3000)
  }
})

let lastLoggedErrorTime = 0
let errorCount = 0

redis.on('connect', () => {
  logger.info('Γ£à Connected to Redis')
  errorCount = 0
})

redis.on('error', (err) => {
  errorCount++
  const now = Date.now()
  // Throttle error logging to once per 60 seconds to prevent terminal spam
  if (now - lastLoggedErrorTime > 60000) {
    lastLoggedErrorTime = now
    logger.warn(`ΓÜá∩╕Å Redis Connection Warning (${err.message}): Unable to connect to Redis. Please check your REDIS_URL or REDIS_HOST/REDIS_PORT environment variables.`)
  }
})

export default redis

import { ZodError } from 'zod'
import logger from '../lib/logger.js'

export default function errorHandler(err, req, res, next) {
  // Handle Zod validation errors
  if (err instanceof ZodError) {
    logger.error('Zod validation failed:', err)
    const fields = {}
    const issues = err.issues || err.errors || []
    issues.forEach((issue) => {
      const path = issue.path.join('.')
      fields[path] = issue.message
    })
    return res.status(400).json({
      error: {
        code: 'VALIDATION_ERROR',
        message: 'Validation failed',
        fields
      }
    })
  }

  // Handle other error structures
  const status = err.status || 500
  const code = err.code || 'INTERNAL_ERROR'
  const message = err.message || 'Something went wrong'

  if (status >= 500) {
    logger.error('Unhandled internal server error:', err)
  }

  const responseError = {
    code,
    message
  }

  if (err.fields) {
    responseError.fields = err.fields
  }

  return res.status(status).json({
    error: responseError
  })
}

// ============================================================
// fileValidationService.js ΓÇö SEC-02
// Server-side file signature (magic bytes) validation.
// Checks: file size, allowed extension, MIME-to-signature match.
// ============================================================
import fs from 'fs/promises'
import path from 'path'

// Known magic byte signatures keyed by allowed MIME type.
// Each value is an array of valid signatures (some types have multiple).
const ALLOWED_SIGNATURES = {
  'application/pdf': [
    Buffer.from([0x25, 0x50, 0x44, 0x46]) // %PDF
  ],
  'image/jpeg': [
    Buffer.from([0xFF, 0xD8, 0xFF, 0xE0]),
    Buffer.from([0xFF, 0xD8, 0xFF, 0xE1]),
    Buffer.from([0xFF, 0xD8, 0xFF, 0xE8])
  ],
  'image/png': [
    Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A])
  ],
  'image/gif': [
    Buffer.from([0x47, 0x49, 0x46, 0x38, 0x39, 0x61]), // GIF89a
    Buffer.from([0x47, 0x49, 0x46, 0x38, 0x37, 0x61])  // GIF87a
  ],
  // DOCX / XLSX / PPTX are ZIP archives ΓÇö same magic bytes
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': [
    Buffer.from([0x50, 0x4B, 0x03, 0x04])
  ]
}

// Allowed file extensions (lowercase)
const ALLOWED_EXTENSIONS = new Set([
  '.pdf', '.jpg', '.jpeg', '.png', '.gif', '.docx'
])

// Maximum allowed file size: 10 MB
const MAX_FILE_SIZE_BYTES = 10 * 1024 * 1024

/**
 * Validates an uploaded file by checking:
 *  1. File size Γëñ MAX_FILE_SIZE_BYTES
 *  2. Extension is in ALLOWED_EXTENSIONS
 *  3. Actual file header matches the declared MIME type
 *
 * @param {string} filePath        - Absolute path to the temp file on disk
 * @param {string} declaredMimetype - MIME type reported by multer / browser
 * @param {string} originalName    - Original filename (for extension check)
 * @returns {{ valid: boolean, errors: string[], quarantine: boolean }}
 */
export async function validateFileSignature(filePath, declaredMimetype, originalName) {
  const errors = []

  // 1. Size check
  try {
    const stat = await fs.stat(filePath)
    if (stat.size > MAX_FILE_SIZE_BYTES) {
      errors.push(`File size ${(stat.size / 1024 / 1024).toFixed(1)} MB exceeds the ${MAX_FILE_SIZE_BYTES / 1024 / 1024} MB limit`)
    }
  } catch {
    errors.push('Could not read file from disk')
    return { valid: false, errors, quarantine: true }
  }

  // 2. Extension check
  const ext = path.extname(originalName).toLowerCase()
  if (!ALLOWED_EXTENSIONS.has(ext)) {
    errors.push(`File extension '${ext}' is not permitted. Allowed: ${[...ALLOWED_EXTENSIONS].join(', ')}`)
  }

  // 3. MIME type must be in our allow-list
  const allowedSigs = ALLOWED_SIGNATURES[declaredMimetype]
  if (!allowedSigs) {
    errors.push(`MIME type '${declaredMimetype}' is not permitted`)
  } else {
    // 4. Magic bytes check ΓÇö read only the first 8 bytes
    try {
      const header = Buffer.alloc(8)
      const fh = await fs.open(filePath, 'r')
      await fh.read(header, 0, 8, 0)
      await fh.close()

      const signatureMatches = allowedSigs.some(sig =>
        header.subarray(0, sig.length).equals(sig)
      )

      if (!signatureMatches) {
        errors.push(
          `File content does not match declared MIME type '${declaredMimetype}'.` +
          ` Possible spoofed extension (actual header: ${header.subarray(0, 4).toString('hex')})`
        )
      }
    } catch {
      errors.push('Could not read file header for validation')
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    quarantine: errors.length > 0
  }
}

/**
 * Creates an object composed of the picked object properties.
 * @param {Object} object - The source object.
 * @param {string[]} keys - The property paths to pick.
 * @returns {Object} Returns the new object.
 */
export default function pick(object, keys) {
  if (!object) return {}
  return keys.reduce((result, key) => {
    if (key in object && object[key] !== undefined) {
      result[key] = object[key]
    }
    return result;
  }, {})
}

import fs from 'fs/promises'
import { PutObjectCommand } from '@aws-sdk/client-s3'
import prisma from '../lib/prisma.js'
import { r2 } from '../lib/r2.js'
import logger from '../lib/logger.js'

export const processFileUpload = async (job) => {
  const { documentId, filePath, r2Key, mimetype, userId } = job.data

  try {
    const logId = documentId || r2Key
    logger.info(`Processing file upload for ${logId}`)

    // Read the file from the temporary disk location
    const fileBuffer = await fs.readFile(filePath)

    // Upload to Cloudflare R2
    await r2.send(new PutObjectCommand({
      Bucket: process.env.R2_BUCKET_NAME || 'documents',
      Key: r2Key,
      Body: fileBuffer,
      ContentType: mimetype
    }))

    logger.info(`Successfully uploaded ${r2Key}`)

  } catch (error) {
    const logId = documentId || r2Key
    logger.error(`Failed to process upload for ${logId}:`, error)

    // Create a notification for the user about the failure
    await prisma.notifications.create({
      data: {
        type: 'SYSTEM_ALERT',
        recipient_filter: `user:${userId}`,
        subject: 'File Upload Failed',
        body_html: `Your upload for ${r2Key.split('/').pop()} failed to process. Please try again.`,
        recipient_count: 1
      }
    })

    throw error // Re-throw to trigger BullMQ retry/fail logic
  } finally {
    // Always clean up the temporary file
    try {
      await fs.unlink(filePath)
    } catch (cleanupError) {
      logger.error(`Failed to delete temporary file ${filePath}:`, cleanupError)
    }
  }
}

